package com.wangc.bill.reference;

import android.content.Context;
import android.content.SharedPreferences;
import android.os.Looper;
import android.os.SystemClock;
import androidx.test.core.app.ApplicationProvider;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BooleanSupplier;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;

/** Real w2 action -> independent MAIN n0; notification does not invent a credit rebuild. */
@RunWith(AndroidJUnit4.class)
public final class OriginalTransferEffectsDeviceTest {
    private static final String DATABASE="reference_original_transfer_effects_test.sqlite";
    private Context context;private ReferenceStore store;private SharedPreferences preferences;private boolean hadBook;private long oldBook;
    @Before public void open(){context=ApplicationProvider.getApplicationContext();context.deleteDatabase(DATABASE);store=new ReferenceStore(context,DATABASE);store.getWritableDatabase();preferences=context.getSharedPreferences("reference_settings",Context.MODE_PRIVATE);hadBook=preferences.contains("current_book");oldBook=preferences.getLong("current_book",1);assertTrue(preferences.edit().putLong("current_book",store.books().get(0).optLong("id")).commit());}
    @After public void close(){if(store!=null)store.close();if(preferences!=null){SharedPreferences.Editor edit=preferences.edit();if(hadBook)edit.putLong("current_book",oldBook);else edit.remove("current_book");edit.commit();}if(context!=null)context.deleteDatabase(DATABASE);}
    private void await(BooleanSupplier condition){long until=SystemClock.uptimeMillis()+8000;while(SystemClock.uptimeMillis()<until){if(condition.getAsBoolean())return;SystemClock.sleep(25);}assertTrue("Actual Transfer effect timed out",condition.getAsBoolean());}
    private OriginalTransferRecord transfer(long semantic,double cost){OriginalTransferRecord r=new OriginalTransferRecord();r.userId=0;r.transferId=semantic;r.fromAssetId=99;r.toAssetId=199;r.cost=cost;r.time=OriginalInstalmentSchedule.parse("2025-01-15","yyyy-MM-dd");return r;}
    private OriginalTransferActions actions(){OriginalFinancialEffects effects=new OriginalFinancialEffects(store,0,0);return new OriginalTransferActions(store,0,effects::transferChanged);}
    private void noBalanceSideEffects(){assertEquals(0,store.scalar("SELECT COUNT(*) n FROM asset_histories"));assertEquals(0,store.scalar("SELECT COUNT(*) n FROM transactions"));}

    @Test public void aSavedTransferPublishesItsOwnMainEventAfterTheActualEntityCommit() throws Exception {List<OriginalFinancialEffects.Event> events=new CopyOnWriteArrayList<>();AtomicBoolean main=new AtomicBoolean();AtomicLong visible=new AtomicLong(-1);CountDownLatch delivered=new CountDownLatch(1);OriginalFinancialEffects.Listener listener=e->{events.add(e);if(e==OriginalFinancialEffects.Event.TRANSFERS_CHANGED){main.set(Looper.myLooper()==Looper.getMainLooper());visible.set(store.scalar("SELECT COUNT(*) n FROM original_transfers"));delivered.countDown();}};OriginalFinancialEffects.subscribe(store,listener);try{OriginalTransferRecord row=transfer(901,5);OriginalTransferActions.Result result=actions().save(row);assertTrue(result.save.saved);assertSame(row,result.record);assertTrue(delivered.await(3,TimeUnit.SECONDS));InstrumentationRegistry.getInstrumentation().waitForIdleSync();assertTrue(main.get());assertEquals(1,visible.get());assertEquals(java.util.Collections.singletonList(OriginalFinancialEffects.Event.TRANSFERS_CHANGED),events);assertEquals(5,new OriginalTransferRepository(store).byIdentity(0,901).cost,0);noBalanceSideEffects();}finally{OriginalFinancialEffects.unsubscribe(store,listener);}}

    @Test public void returnedFalseAndUpdateStillNotifyWhileTheSilentActionDoesNot() throws Exception {List<OriginalFinancialEffects.Event> events=new CopyOnWriteArrayList<>();OriginalFinancialEffects.Listener listener=events::add;OriginalFinancialEffects.subscribe(store,listener);try{OriginalTransferActions actions=actions();store.getWritableDatabase().execSQL("CREATE TEMP TRIGGER reject_transfer_effect BEFORE INSERT ON original_transfers BEGIN SELECT RAISE(ABORT,'synthetic rejection'); END");OriginalTransferActions.Result failed=actions.save(transfer(901,5));assertFalse(failed.save.saved);await(()->events.size()==1);assertEquals(0,store.scalar("SELECT COUNT(*) n FROM original_transfers"));store.getWritableDatabase().execSQL("DROP TRIGGER reject_transfer_effect");OriginalTransferRecord silent=transfer(902,6);assertTrue(actions.saveSilently(silent).save.saved);InstrumentationRegistry.getInstrumentation().waitForIdleSync();assertEquals(java.util.Collections.singletonList(OriginalFinancialEffects.Event.TRANSFERS_CHANGED),events);silent.cost=7;assertTrue(actions.update(silent).save.saved);await(()->events.size()==2);InstrumentationRegistry.getInstrumentation().waitForIdleSync();assertEquals(java.util.Arrays.asList(OriginalFinancialEffects.Event.TRANSFERS_CHANGED,OriginalFinancialEffects.Event.TRANSFERS_CHANGED),events);assertEquals(7,new OriginalTransferRepository(store).byIdentity(0,902).cost,0);noBalanceSideEffects();}finally{OriginalFinancialEffects.unsubscribe(store,listener);}}

    @Test public void theTransferEventPreservesAnExistingCreditRevisionUntilARealRefreshIsRequested() throws Exception {AssetRepository.Definition credit=new AssetRepository.Definition("合成转账事件信用账户",2,null);credit.assetNumber=-20;credit.outAccountDate="每月1号";credit.inAccountDate="出账日1";long account=store.assetRepository().insertRecovered(0,99,1,0,credit);OriginalTransferRecord row=transfer(901,5);new OriginalTransferRepository(store).saveOriginalRaw(row);CountDownLatch initialized=new CountDownLatch(1);OriginalFinancialEffects.Listener startup=e->{if(e==OriginalFinancialEffects.Event.CREDIT_CHANGED)initialized.countDown();};OriginalFinancialEffects.subscribe(store,startup);try{await(()->OriginalFinancialEffects.creditStatus(store,0,0,99)==OriginalFinancialEffects.CreditStatus.READY);assertTrue(initialized.await(3,TimeUnit.SECONDS));}finally{OriginalFinancialEffects.unsubscribe(store,startup);}long before=OriginalFinancialEffects.creditRevision(store,0,0,99);assertEquals(5,OriginalFinancialEffects.creditStatements(store,0,0,99).get(0).getNumber(),0);List<OriginalFinancialEffects.Event> events=new CopyOnWriteArrayList<>();CountDownLatch transferred=new CountDownLatch(1),rebuilt=new CountDownLatch(1);OriginalFinancialEffects.Listener listener=e->{events.add(e);if(e==OriginalFinancialEffects.Event.TRANSFERS_CHANGED)transferred.countDown();if(e==OriginalFinancialEffects.Event.CREDIT_CHANGED)rebuilt.countDown();};OriginalFinancialEffects.subscribe(store,listener);try{row.cost=9;assertTrue(actions().update(row).save.saved);assertTrue(transferred.await(3,TimeUnit.SECONDS));InstrumentationRegistry.getInstrumentation().waitForIdleSync();assertEquals(before,OriginalFinancialEffects.creditRevision(store,0,0,99));assertEquals(5,OriginalFinancialEffects.creditStatements(store,0,0,99).get(0).getNumber(),0);assertEquals(java.util.Collections.singletonList(OriginalFinancialEffects.Event.TRANSFERS_CHANGED),events);new OriginalFinancialEffects(store,0,0).creditRefresh(99);assertTrue(rebuilt.await(3,TimeUnit.SECONDS));await(()->OriginalFinancialEffects.creditStatus(store,0,0,99)==OriginalFinancialEffects.CreditStatus.READY&&OriginalFinancialEffects.creditRevision(store,0,0,99)>before);assertEquals(9,OriginalFinancialEffects.creditStatements(store,0,0,99).get(0).getNumber(),0);assertEquals(java.util.Arrays.asList(OriginalFinancialEffects.Event.TRANSFERS_CHANGED,OriginalFinancialEffects.Event.CREDIT_CHANGED),events);assertEquals(-20,store.assetRepository().byRowId(account).optDouble("asset_number"),0);noBalanceSideEffects();}finally{OriginalFinancialEffects.unsubscribe(store,listener);}}
}
